mapper.select:
SELECT s.schedule_id AS scheduleId, s.store_id AS storeId, st.store_name AS storeName, s.course_id AS courseId, c.course_name AS courseName, c.course_type AS courseType, s.coach_id AS coachId, coach.coach_name AS coachName, s.schedule_date AS scheduleDate, s.start_time AS startTime, s.end_time AS endTime, s.capacity, s.reserved_count AS reservedCount, s.signed_count AS signedCount, s.schedule_status AS scheduleStatus FROM fit_course_schedule s INNER JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0' LEFT JOIN fit_store st ON st.store_id = s.store_id AND st.del_flag = '0' LEFT JOIN fit_coach coach ON coach.coach_id = s.coach_id AND coach.del_flag = '0' WHERE s.del_flag = '0' AND s.coach_id = #{coachId}
AND s.schedule_date = CURDATE()
AND s.schedule_date = DATE_ADD(CURDATE(), INTERVAL 1 DAY)
AND YEARWEEK(s.schedule_date, 1) = YEARWEEK(CURDATE(), 1)
AND s.schedule_date = #{bo.scheduleDate}
ORDER BY s.start_time ASC, s.schedule_id DESC

mapper.sql:
SELECT cr.checkin_id AS checkinId, r.reservation_id AS reservationId, r.schedule_id AS scheduleId, s.store_id AS storeId, st.store_name AS storeName, s.course_id AS courseId, c.course_name AS courseName, c.course_type AS courseType, s.schedule_date AS scheduleDate, s.start_time AS startTime, s.end_time AS endTime, m.member_id AS memberId, COALESCE(m.real_name, m.nickname) AS memberName, m.mobile AS memberMobile, r.card_id AS cardId, r.reservation_type AS reservationType, mc.card_name AS cardName, mc.plan_type AS planType, mc.remain_times AS remainTimes,
cr.checkin_time AS checkinTime, cr.consume_times AS consumeTimes, cr.consume_amount AS consumeAmount, cr.operator_user_id AS operatorUserId, cr.checkin_status AS checkinStatus, cr.remark FROM fit_course_reservation r INNER JOIN fit_course_schedule s ON s.schedule_id = r.schedule_id AND s.tenant_id=r.tenant_id AND s.del_flag = '0' LEFT JOIN fit_checkin_record cr ON cr.reservation_id = r.reservation_id AND cr.tenant_id=r.tenant_id AND cr.del_flag = '0' INNER JOIN fit_member m ON m.member_id = r.member_id AND m.tenant_id=r.tenant_id AND m.del_flag = '0' LEFT JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0' LEFT JOIN fit_store st ON st.store_id = s.store_id AND st.del_flag = '0' LEFT JOIN fit_member_card mc ON mc.card_id = r.card_id AND mc.del_flag = '0' WHERE r.del_flag = '0' AND r.reservation_status IN ('reserved','signed')
AND s.coach_id = #{coachId}

mapper.select:
SELECT cr.tenant_id AS tenantId, cr.checkin_id AS checkinId, cr.reservation_id AS reservationId, cr.schedule_id AS scheduleId, s.store_id AS storeId, s.course_id AS courseId, c.course_name AS courseName, s.coach_id AS coachId, cr.member_id AS memberId, COALESCE(m.real_name, m.nickname) AS memberName, cr.card_id AS cardId, mc.card_name AS cardName, mc.card_status AS cardStatus, mc.plan_type AS planType, mc.bind_coach_id AS bindCoachId, mc.remain_times AS remainTimes, mc.balance_amount AS balanceAmount, cr.operator_user_id AS operatorUserId, cr.checkin_status AS checkinStatus FROM fit_checkin_record cr INNER JOIN fit_course_schedule s ON s.schedule_id = cr.schedule_id AND s.del_flag = '0' LEFT JOIN fit_course_reservation r ON r.reservation_id = cr.reservation_id AND r.del_flag = '0' INNER JOIN fit_member m ON m.member_id = cr.member_id AND m.del_flag = '0' LEFT JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0' LEFT JOIN fit_member_card mc ON mc.card_id = cr.card_id AND mc.del_flag = '0'
WHERE cr.del_flag = '0' AND s.coach_id = #{coachId} AND cr.reservation_id = #{reservationId}
LIMIT 1

SELECT m.member_id AS memberId, m.real_name AS realName, m.nickname, m.mobile, m.avatar_url AS avatarUrl, m.last_visit_time AS lastVisitTime, mc.card_id AS cardId, mc.card_name AS cardName, mc.remain_times AS remainTimes, mc.balance_amount AS balanceAmount, ( SELECT s2.start_time FROM fit_course_schedule s2 INNER JOIN fit_course_reservation r2 ON r2.schedule_id = s2.schedule_id AND r2.del_flag = '0' AND r2.member_id = m.member_id AND r2.reservation_status = 'reserved' WHERE s2.del_flag = '0' AND s2.coach_id = #{coachId} AND s2.start_time > NOW() ORDER BY s2.start_time ASC LIMIT 1 ) AS nextClassTime, ( SELECT c2.course_name FROM fit_course_schedule s2 INNER JOIN fit_course c2 ON c2.course_id = s2.course_id AND c2.del_flag = '0' INNER JOIN fit_course_reservation r2 ON r2.schedule_id = s2.schedule_id AND r2.del_flag = '0' AND r2.member_id = m.member_id AND r2.reservation_status = 'reserved' WHERE s2.del_flag = '0' AND s2.coach_id = #{coachId} AND s2.start_time > NOW() ORDER BY s2.start_time ASC LIMIT 1 ) AS nextCourseName, IFNULL((SELECT COUNT(1) FROM fit_checkin_record cr WHERE cr.del_flag = '0' AND cr.member_id = m.member_id AND cr.operator_user_id IS NOT NULL), 0) AS totalCheckinCount FROM fit_member_card mc INNER JOIN fit_member m ON m.member_id = mc.member_id AND m.del_flag = '0' WHERE mc.del_flag = '0' AND mc.bind_coach_id = #{coachId}
AND (m.real_name LIKE CONCAT('%', #{keyword}, '%') OR m.nickname LIKE CONCAT('%', #{keyword}, '%') OR m.mobile LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY mc.create_time DESC, mc.card_id DESC
